const apply = () => { document.querySelectorAll('.segmented__btn[role="radio"]').forEach((b, i) => { const want = i === 0 ? 'true' : 'false'; if (b.getAttribute('aria-checked') !== want) b.setAttribute('aria-checked', want); }); };
const mo = new MutationObserver(() => { mo.disconnect(); apply(); mo.observe(document.body, { childList: true, subtree: true, attributes: true }); });
